SELECT device_code, DATE_TRUNC('HOUR', reading_ts) AS hour_window, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, CORR(pressure, status_bits) AS corr_pressure_status_bits, GROUPING(device_code) AS grouping_id FROM device_readings GROUP BY CUBE (device_code, DATE_TRUNC('HOUR', reading_ts)) ORDER BY hour_window NULLS LAST
